 "content": "from collections import Counter


def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    # A solid non-background row/column is a repetition separator.
    row_seps = [(r, g[r][0]) for r in range(h)
                if g[r][0] != bg and all(x == g[r][0] for x in g[r])]
    col_seps = [(c, g[0][c]) for c in range(w)
                if g[0][c] != bg and all(g[r][c] == g[0][c] for r in range(h))]
    if not row_seps and not col_seps:
        return g

    # Prefer the axis with the most separator lines.
    horizontal = len(row_seps) >= len(col_seps)
    if horizontal:
        lines = [p for p, _ in row_seps]
        intervals = []
        start = 0
        for p in lines:
            if p > start:
                intervals.append((start, p))
            start = p + 1
        if start < h:
            intervals.append((start, h))
        if len(intervals) < 2:
            return g
        def score(a, b):
            return sum(x != bg for row in g[a:b] for x in row)
        src = max(intervals, key=lambda ab: score(*ab))
        sh = src[1] - src[0]
        for a, b in intervals:
            if (a, b) == src:
                continue
            for r in range(a, b):
                sr = src[0] + (r - a) % sh
                g[r] = g[sr][:]
    else:
        lines = [p for p, _ in col_seps]
        intervals = []
        start = 0
        for p in lines:
            if p > start:
                intervals.append((start, p))
            start = p + 1
        if start < w:
            intervals.append((start, w))
        if len(intervals) < 2:
            return g
        def score(a, b):
            return sum(g[r][c] != bg for r in range(h) for c in range(a, b))
        src = max(intervals, key=lambda ab: score(*ab))
        sw = src[1] - src[0]
        for a, b in intervals:
            if (a, b) == src:
                continue
            for c in range(a, b):
                sc = src[0] + (c - a) % sw
                for r in range(h):
                    g[r][c] = g[r][sc]
    return g
